class Solution{public:int minSwaps(vector<int>&a){int n=a.size(),count=0;long long c0=0,c1=0;for(int i=0;i<n;i++)if(a[i]&1){c0+=abs(1LL*i-2LL*count);c1+=abs(1LL*i-(2LL*count+1));count++;}long long best=LLONG_MAX;if(count==(n+1)/2)best=c0;if(count==n/2)best=min(best,c1);return best==LLONG_MAX?-1:(int)best;}};